// External final seal for the correction. Hashes commands 01-16 in full,
// plus this command's cmd.txt. out, err, and exit for this command are
// written by the wrapper after exit. Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

function fileRec(name) {
  const data = readFileSync(resolve(name));
  return { path: name.replaceAll('\\', '/'), sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}
function commandRec(n, full) {
  const nn = String(n).padStart(2, '0');
  const cmdText = readFileSync(resolve('work/out/cmd/' + nn + '.cmd.txt'), 'utf8');
  const files = { cmd: fileRec('work/out/cmd/' + nn + '.cmd.txt') };
  let status = null;
  let scripts = null;
  let wrapper = null;
  if (full) {
    const exitDoc = JSON.parse(readFileSync(resolve('work/out/cmd/' + nn + '.exit'), 'utf8'));
    status = exitDoc.status;
    scripts = exitDoc.scripts || [];
    wrapper = exitDoc.wrapper_sha256;
    files.out = fileRec('work/out/cmd/' + nn + '.out');
    files.err = fileRec('work/out/cmd/' + nn + '.err');
    files.exit = fileRec('work/out/cmd/' + nn + '.exit');
  }
  return {
    n,
    requested: (cmdText.match(/^requested: (.*)$/m) || [])[1] || '',
    status,
    wrapper_sha256: wrapper,
    scripts,
    files,
  };
}
const commands = [];
for (let n = 1; n <= 16; n++) commands.push(commandRec(n, true));
commands.push(commandRec(17, false));
const doc = {
  task: 'T10-afon-profile-storage-5b82',
  sealed: 'External final seal. Commands 01-16 include cmd, out, err, and exit. Command 17 cmd.txt is hashed. 17.out, 17.err, and 17.exit are written by the wrapper after this process exits. No emulator module was loaded.',
  manifest: fileRec('work/evidence-manifest.json'),
  result: fileRec('work/result.md'),
  encoding: fileRec('work/out/encoding.md'),
  reader_audit: fileRec('work/out/reader-audit.md'),
  seal_script: fileRec('work/scripts/seal_t10d.mjs'),
  commands,
};
writeFileSync(resolve('work/out/seal-t10d.json'), JSON.stringify(doc, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: true, commands: commands.length, manifest: doc.manifest.sha256 }) + '\n');
